export const analyticsMarkup="<section id=\"profileAnalytics\" class=\"view\"><section class=\"dashboard-chart white-card\"><div class=\"chart-heading\"><div><h2>Solving rhythm</h2><p>First accepted solves, grouped by date.</p></div><div class=\"chart-filters\"><select id=\"graphMode\" aria-label=\"Chart frequency\"><option value=\"daily\">Daily</option><option value=\"monthly\">Monthly</option><option value=\"yearly\">Yearly</option></select><input id=\"graphMonth\" type=\"month\" aria-label=\"Chart month\"><input id=\"graphYear\" type=\"number\" min=\"2000\" max=\"2200\" aria-label=\"Chart year\" hidden><select id=\"graphTopic\" aria-label=\"Chart topic\"><option value=\"\">All topics</option></select></div></div><div id=\"graphLegend\" class=\"graph-legend\"></div><div class=\"graph-scroll\"><svg id=\"frequencyChart\" viewBox=\"0 0 900 225\" role=\"img\" aria-label=\"Problem solving frequency comparison\"></svg></div><div class=\"comparison-controls\"><span>Compare with friends</span><select id=\"compareOne\" aria-label=\"First friend\"><option value=\"\">Choose a friend</option></select><select id=\"compareTwo\" aria-label=\"Second friend\"><option value=\"\">Choose a friend</option></select></div><p id=\"dashboardMessage\" class=\"muted\" role=\"status\"></p><p class=\"chart-footnote\">Dates use UTC for consistent comparisons. Practice records are self-reported.</p></section><section class=\"white-card topic-summary\"><div><h2>Patterns growing</h2><p>Solved topics in the selected period.</p></div><div id=\"topicBreakdown\"></div></section></section>  ";
